#include<iostream>
#include<cstdio>
#include<cstring>
#include<algorithm>
using namespace std;

int n, k, p;

int bin_pow(int base, int exp) {
    int res = 1;
    int cur = base;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * cur % p;
        cur = (long long)cur * cur % p;
        exp >>= 1;
    }
    return res;
}

int get_bit(int x) {
    return x & (-x);
}

int cache_dp[30][250005];
int factorials[250005], inv_factorials[250005];

void precompute() {
    factorials[0] = 1;
    for (int i = 1; i <= n; i++)
        factorials[i] = (long long)factorials[i - 1] * i % p;
    inv_factorials[n] = bin_pow(factorials[n], p - 2);
    for (int i = n; i >= 1; i--)
        inv_factorials[i - 1] = (long long)inv_factorials[i] * i % p;
}

int compute(int index, int mask) {
    if (cache_dp[index][mask] != -1)
        return cache_dp[index][mask];
    if (mask == 0) {
        int res = factorials[n];
        for (int i = 1; i <= index; i++)
            res = (long long)res * (k - i + 1) % p;
        return cache_dp[index][mask] = res;
    }
    int total = 0;
    int rem = mask - get_bit(mask);
    for (int subset = rem; subset; subset = (subset - 1) & rem)
        total = (total + (long long)inv_factorials[mask - subset] * compute(index + 1, subset)) % p;
    total = (total + (long long)inv_factorials[mask] * compute(index + 1, 0)) % p;
    return cache_dp[index][mask] = total;
}

int main() {
    scanf("%d %d %d", &n, &k, &p);
    int answer = 1;
    for (int i = 1; i <= n; i++)
        answer = (long long)answer * k % p;
    if (n % 2 == 0) {
        memset(cache_dp, -1, sizeof(cache_dp));
        precompute();
        answer = (answer - compute(0, n) + p) % p;
    }
    printf("%d\n", answer);
    return 0;
}
